def _caso(clave, nombre, actor, descripcion, precondiciones, flujo, alternos, postcondicion):
    filas = [
        ["Clave", clave],
        ["Nombre", nombre],
        ["Actor", actor],
        ["Descripción", descripcion],
        ["Precondiciones", precondiciones],
        ["Flujo principal", " ".join(f"{i}. {paso}" for i, paso in enumerate(flujo, start=1))],
        ["Flujos alternos", alternos],
        ["Postcondición", postcondicion],
    ]
    return ("tabla", f"Caso de uso {clave}: {nombre.lower()}.", ["Elemento", "Descripción"], filas, [3.4, 11.6])


